# 1. Identify the university that won every time it appeared in the SEC baseball tourney. (independent, support=[School | Appearances | Championships])
for school, appearances, championships in zip(table["School"], table["Appearances"], table["Championships"]):
    if appearances == championships:
        winning_school = school

# 2. What is the number of national titles for that university? (depends on 1, support=[School | Appearances | Championships])
for school, appearances, championships in zip(table["School"], table["Appearances"], table["Championships"]):
    if school == winning_school:
        national_titles = championships

print(national_titles)
#DONE
```

